const path = require("path");
const encode = require("./encode");

const srcRegex = /<img .*?src=["'](.+?)["|'].*?>/gi;
const srcsetRegex = /<img .*?srcset=["'](.+?)["'].*?>/gi;

module.exports = function (str) {
    const hexo = this;
    const config = hexo.config.filter_base64;

    let matches;
    let newStr = str;

    if (config.enabled) {
        while (matches = srcRegex.exec(str)) {
            const src = matches[1];
            if (!/^(data|http:\/\/|https:\/\/)/.test(src)) {
                const filePath = path.resolve(hexo.theme_dir, "source", src[0] === "/" ? `.${src}` : src);
                const encoded = encode(filePath, hexo);
                if (encoded) newStr = newStr.replace(matches[0], matches[0].replace(src, encoded));
            }
        }
        while (matches = srcsetRegex.exec(str)) {
            const match = matches[1];
            const srcset = match.split(",").map(s =>
                s.trim()
                    .replace(/\s{2,}/g, " ")
                    .split(" ")[0]
            );
            for (let src of srcset) {
                if (!/^(data|http:\/\/|https:\/\/)/.test(src)) {
                    const filePath = path.resolve(hexo.theme_dir, "source", src[0] === "/" ? `.${src}` : src);
                    const encoded = encode(filePath, hexo);
                    if (encoded) newStr = newStr.replace(matches[0], matches[0].replace(src, encoded));
                }
            }
        }
    }
    return newStr
};
